from functools import lru_cache

@lru_cache(maxsize=None)
def count_valid(rem: int, cur_sum: int, prod_mod: int, target_sum: int) -> int:
    # Prune paths that can never reach the target sum
    if cur_sum + rem * 9 < target_sum:
        return 0

    if rem == 0:
        return 1 if (cur_sum == target_sum and prod_mod == 0) else 0

    ans = 0
    for d in range(10):
        next_sum = cur_sum + d
        if next_sum <= target_sum:
            ans += count_valid(rem - 1, next_sum, (prod_mod * d) % target_sum, target_sum)
    return ans

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = [int(c) for c in str(n)]
            length = len(digits)
            ans = 0

            # The maximum possible sum of digits for a number of this length
            max_sum = 9 * length

            for target_sum in range(1, max_sum + 1):
                # 1. Count valid numbers with fewer digits than `n`
                for L in range(1, length):
                    for d in range(1, 10):
                        if d <= target_sum:
                            ans += count_valid(L - 1, d, d % target_sum, target_sum)

                # 2. Count valid numbers with exactly the same number of digits as `n`
                cur_sum = 0
                prod_mod = 1

                for i, d in enumerate(digits):
                    start = 1 if i == 0 else 0
                    # Try all valid digits strictly smaller than the current digit in `n`
                    for x in range(start, d):
                        if cur_sum + x <= target_sum:
                            ans += count_valid(length - 1 - i, cur_sum + x, (prod_mod * x) % target_sum, target_sum)

                    # Accumulate for the prefix match
                    cur_sum += d
                    prod_mod = (prod_mod * d) % target_sum

                    if cur_sum > target_sum:
                        break
                else:
                    # Check if `n` itself is a beautiful number for this target_sum
                    if cur_sum == target_sum and prod_mod == 0:
                        ans += 1

            return ans

        return count_up_to(r) - count_up_to(l - 1)
